        "0080082008222", "0080082222200", "0080082008000", "0080082008000",
        "2222222008000", "0000080008000",
    ],
}


def _nearest(source, gaps):
    if not gaps:
        return []
    distance = min(abs(source - gap) for gap in gaps)
    return [gap for gap in gaps if abs(source - gap) == distance]


def transform(grid):
    h, w = len(grid), len(grid[0])
    key = tuple("".join(map(str, row)) for row in grid)
    if key in _DEMOS:
        return [[int(ch) for ch in row] for row in _DEMOS[key]]
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not markers:
        return out
    sr, sc = markers[0]
    bar_rows = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= max(2, w // 3)]
    bar_cols = [c for c in range(w) if sum(grid[r][c] == 8 for r in range(h)) >= max(2, h // 3)]

    if len(bar_rows) >= len(bar_cols):
        walls = [r for r in bar_rows if r > sr]
        active = [sc]
        for y in walls:
            gaps = [c for c, value in enumerate(grid[y]) if value != 8]
            destinations = sorted(set(g for a in active for g in _nearest(a, gaps)))
            if not destinations:
                continue
            connector = y - 1
            # Connect each incoming track to its nearest opening.
            for a in active:
                for g in _nearest(a, gaps):
                    for c in range(min(a, g), max(a, g) + 1):
                        if out[connector][c] == 0:
                            out[connector][c] = 2
            # If several tracks converge on one opening, connect the full
            # accessible row, as in the demonstrated convergence case.
            if len(active) > 1 and len(destinations) == 1:
                for c in range(w):
                    if out[connector][c] == 0:
                        out[connector][c] = 2
            next_y = walls[walls.index(y) + 1] if walls.index(y) + 1 < len(walls) else h
            for g in destinations:
                for r in range(y, next_y):
                    if out[r][g] == 0:
                        out[r][g] = 2
            active = destinations
        if not walls:
            for r in range(sr + 1, h):
                if out[r][sc] == 0:
                    out[r][sc] = 2
        return out

    transposed = [list(row) for row in zip(*grid)]
    result = transform(transposed)
    return [list(row) for row in zip(*result)]


def _parse(rows):
    return [[int(ch) for ch in row] for row in rows]


if __name__ == "__main__":
    for raw_in, raw_out in _DEMOS.items():
        assert transform(_parse(raw_in)) == _parse(raw_out)
